#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Enemies;
using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Shells;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Enemies;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using MVZ2Logic.Saves;
using PVZEngine;
using PVZEngine.Buffs;
using PVZEngine.Callbacks;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Models;
using PVZEngine.Modifiers;

namespace MVZ2.GameContent.Enemies
{
    [AutoEntityBehaviourDefinition(VanillaEnemyNames.zombinator)]
    public class Zombinator : EntityBehaviourDefinition
    {
        public Zombinator(string nsp, string name) : base(nsp, name)
        {
            AddModifier(new NamespaceIDModifier(EngineEntityProps.SHELL, SetOperator.SetIfNotNull, PROP_SHELL));
            AddModifier(new MaxHealthModifier(NumberOperator.Set, PROP_MAX_HEALTH));
            AddModifier(new FloatModifier(VanillaEnemyProps.SPEED, NumberOperator.Set, PROP_SPEED));
            AddModifier(new NamespaceIDModifier(LogicEnemyProps.CRY_SOUND, SetOperator.SetIfNotNull, PROP_CRY_SOUND));
            AddModifier(new NamespaceIDModifier(LogicEntityProps.DEATH_SOUND, SetOperator.SetIfNotNull, PROP_DEATH_SOUND));
            AddModifier(new BooleanModifier(VanillaEntityProps.IS_UNDEAD, BooleanOperator.Or, PROP_UNDEAD));
        }

        public override void Init(Entity entity)
        {
            if (entity.IsPreviewEnemy())
            {
                if (Global.Saves.IsEnemyUnlocked(VanillaEnemyID.zombinator))
                {
                    SwitchPhase(entity, PHASE_3);
                }
                else
                {
                    var param = new SpawnParams();
                    param.SetProperty(LogicEnemyProps.PREVIEW_ENEMY, true);
                    var spawned = entity.Level.Spawn(VanillaEnemyID.zombie, entity.Position, null, param);
                    if (spawned != null)
                    {
                        spawned.RemoveBuffs<BoatBuff>();
                        spawned.SetModelProperty("HasBoat", false);
                    }
                    entity.Remove();
                }
            }
            else
            {
                SwitchPhase(entity, PHASE_1);
            }
        }
        public override void PreDeath(Entity entity, DeathInfo deathInfo, CallbackResult<bool> result)
        {
            base.PreDeath(entity, deathInfo, result);
            if (deathInfo.HasEffect(VanillaDamageEffects.DROWN) || deathInfo.HasEffect(VanillaDamageEffects.FALL_OFF))
                return;
            if (!entity.ShouldTriggerDeathEffects(deathInfo))
                return;
            var phase = GetPhase(entity);
            if (phase < PHASE_3)
            {
                entity.Velocity += entity.GetFacingDirection() * -KNOCKBACK_SPEED;
                SwitchPhase(entity, phase + 1);
                entity.Health = entity.GetMaxHealth();
                Explosion.Spawn(entity, entity.GetCenter(), 40);
                entity.PlaySound(VanillaSoundID.largeExplosion);
                result.SetFinalValue(false);
            }
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            if (deathInfo.HasEffect(VanillaDamageEffects.DROWN) || deathInfo.HasEffect(VanillaDamageEffects.FALL_OFF))
                return;
            if (deathInfo.HasEffect(VanillaDamageEffects.REMOVE_ON_DEATH))
                return;
            var phase = GetPhase(entity);
            Explosion.Spawn(entity, entity.GetCenter(), 40);
            entity.PlaySound(VanillaSoundID.largeExplosion);
            entity.Remove();
        }
        public static void SwitchPhase(Entity entity, int phase)
        {
            SetPhase(entity, phase);
            entity.SetModelProperty("Phase", phase);
            UpdatePhaseProperties(entity);
        }
        public static void UpdatePhaseProperties(Entity entity)
        {
            var phase = GetPhase(entity);
            switch (phase)
            {
                case PHASE_1:
                    entity.SetProperty(PROP_SHELL, PHASE_1_SHELL);
                    entity.SetProperty(PROP_MAX_HEALTH, PHASE_1_MAX_HEALTH);
                    entity.SetProperty(PROP_SPEED, PHASE_1_SPEED);
                    entity.SetProperty(PROP_CRY_SOUND, PHASE_1_CRY_SOUND);
                    entity.SetProperty(PROP_DEATH_SOUND, PHASE_1_DEATH_SOUND);
                    entity.SetProperty(PROP_UNDEAD, PHASE_1_UNDEAD);
                    break;
                case PHASE_2:
                    entity.SetProperty(PROP_SHELL, PHASE_2_SHELL);
                    entity.SetProperty(PROP_MAX_HEALTH, PHASE_2_MAX_HEALTH);
                    entity.SetProperty(PROP_SPEED, PHASE_2_SPEED);
                    entity.SetProperty(PROP_CRY_SOUND, PHASE_2_CRY_SOUND);
                    entity.SetProperty(PROP_DEATH_SOUND, PHASE_2_DEATH_SOUND);
                    entity.SetProperty(PROP_UNDEAD, PHASE_2_UNDEAD);
                    break;
                case PHASE_3:
                    entity.SetProperty(PROP_SHELL, PHASE_3_SHELL);
                    entity.SetProperty(PROP_MAX_HEALTH, PHASE_3_MAX_HEALTH);
                    entity.SetProperty(PROP_SPEED, PHASE_3_SPEED);
                    entity.SetProperty(PROP_CRY_SOUND, PHASE_3_CRY_SOUND);
                    entity.SetProperty(PROP_DEATH_SOUND, PHASE_3_DEATH_SOUND);
                    entity.SetProperty(PROP_UNDEAD, PHASE_3_UNDEAD);
                    break;
            }
        }
        public static int GetPhase(Entity entity) => entity.GetProperty<int>(PROP_PHASE);
        public static void SetPhase(Entity entity, int value) => entity.SetProperty(PROP_PHASE, value);
        public const int PHASE_1 = 0;
        public const int PHASE_2 = 1;
        public const int PHASE_3 = 2;
        public const float KNOCKBACK_SPEED = 0;

        public static readonly NamespaceID PHASE_1_SHELL = VanillaShellID.flesh;
        public const float PHASE_1_MAX_HEALTH = 200;
        public const float PHASE_1_SPEED = 1;
        public static readonly NamespaceID PHASE_1_CRY_SOUND = VanillaSoundID.zombieCry;
        public static readonly NamespaceID PHASE_1_DEATH_SOUND = VanillaSoundID.zombieDeath;
        public const bool PHASE_1_UNDEAD = true;

        public static readonly NamespaceID PHASE_2_SHELL = VanillaShellID.metal;
        public const float PHASE_2_MAX_HEALTH = 400;
        public const float PHASE_2_SPEED = 2;
        public static readonly NamespaceID PHASE_2_CRY_SOUND = VanillaSoundID.zombinatorCry;
        public static readonly NamespaceID PHASE_2_DEATH_SOUND = VanillaSoundID.zombinatorDeath;
        public const bool PHASE_2_UNDEAD = false;

        public static readonly NamespaceID PHASE_3_SHELL = VanillaShellID.metal;
        public const float PHASE_3_MAX_HEALTH = 600;
        public const float PHASE_3_SPEED = 4;
        public static readonly NamespaceID PHASE_3_CRY_SOUND = VanillaSoundID.zombinatorCry;
        public static readonly NamespaceID PHASE_3_DEATH_SOUND = VanillaSoundID.zombinatorDeath;
        public const bool PHASE_3_UNDEAD = false;

        public static readonly PropertyMeta<int> PROP_PHASE = new VanillaEntityPropertyMeta<int>("phase");
        public static readonly PropertyMeta<NamespaceID> PROP_SHELL = new VanillaEntityPropertyMeta<NamespaceID>("shell");
        public static readonly PropertyMeta<float> PROP_MAX_HEALTH = new VanillaEntityPropertyMeta<float>("max_health", PHASE_3_MAX_HEALTH);
        public static readonly PropertyMeta<float> PROP_SPEED = new VanillaEntityPropertyMeta<float>("speed", PHASE_3_SPEED);
        public static readonly PropertyMeta<NamespaceID> PROP_CRY_SOUND = new VanillaEntityPropertyMeta<NamespaceID>("cry_sound");
        public static readonly PropertyMeta<NamespaceID> PROP_DEATH_SOUND = new VanillaEntityPropertyMeta<NamespaceID>("death_sound");
        public static readonly PropertyMeta<bool> PROP_UNDEAD = new VanillaEntityPropertyMeta<bool>("undead", PHASE_3_UNDEAD);
    }
}
